// Shuffle once per term; save the result so reloads cannot reroll decisions.
function createDecisionOrder(count,total=30,prefix=[0],random=Math.random){
const used=new Set(prefix);
const pool=Array.from({length:count},(_,i)=>i).filter(i=>!used.has(i));
for(let i=pool.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
return prefix.concat(pool).slice(0,total);
}
